<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\{SupportTicket,SupportMessage}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class SupportController extends Controller { public function index(Request $r){$u=$r->attributes->get('app_user');return response()->json(['ok'=>true,'tickets'=>SupportTicket::where('user_id',$u->id)->latest()->get()]);} public function store(Request $r){$d=$r->validate(['subject'=>'required|string|max:180','message'=>'required|string|max:5000','category'=>'required|string|max:80','priority'=>'nullable|in:low,normal,high,urgent']);$u=$r->attributes->get('app_user');$t=SupportTicket::create(['ticket_no'=>'SUP-'.strtoupper(Str::random(8)),'user_id'=>$u->id,'subject'=>$d['subject'],'category'=>$d['category'],'priority'=>$d['priority']??'normal','status'=>'open']);SupportMessage::create(['support_ticket_id'=>$t->id,'sender_type'=>'user','sender_id'=>$u->id,'message'=>$d['message']]);return response()->json(['ok'=>true,'ticket'=>$t],201);} }
